const params=new URLSearchParams(location.search);if(params.get('view')==='workspace'){document.querySelector('#home-view').hidden=true;document.querySelector('#workspace-view').hidden=false}if(params.has('embed'))document.body.classList.add('embedded');
if(params.has('embed')){const report=()=>parent.postMessage({type:'huiqiao-preview-height',height:Math.ceil(document.body.getBoundingClientRect().height)},location.origin==='null'?'*':location.origin);addEventListener('load',report);new ResizeObserver(report).observe(document.body)}
const mentors=[{name:'MJ',role:'产品设计方向',topic:'让作品集讲清楚你的思考',text:'从项目结构、设计取舍到表达方式，一起梳理作品集中的关键内容。',domain:'design',tags:'作品集 产品 设计 创意'},{name:'TASK',role:'职业经验分享',topic:'职业选择，从具体问题开始',text:'聊一聊你的经历与期待，把模糊的职业困惑转化为下一步可以尝试的行动。',domain:'career',tags:'职业 发展 转型 方向'},{name:'TINA',role:'简历与面试交流',topic:'让你的经验被更好地理解',text:'围绕简历表达与面试准备，练习清楚说明自己做过的事情。',domain:'interview',tags:'简历 面试 求职'}];let domain='all',query='';const dialog=document.querySelector('#web-dialog');function show(content){document.querySelector('#dialog-content').innerHTML=content;dialog.showModal()}document.querySelector('.dialog-close').onclick=()=>dialog.close();dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dialog.close()}});
function render(){const filtered=mentors.filter(m=>(domain==='all'||m.domain===domain)&&(!query||(m.name+' '+m.topic+' '+m.tags+' '+m.text).toLowerCase().includes(query.toLowerCase())));document.querySelector('#mentor-grid').innerHTML=filtered.map(m=>`<article class="mentor-card"><div class="mentor-top"><div class="avatar">${m.name.slice(0,2)}</div><div><h3>${m.name}</h3><small>${m.role}</small></div></div><h3>${m.topic}</h3><p>${m.text}</p><button data-mentor="${m.name}">了解这位桥友 ↗</button></article>`).join('');document.querySelector('#empty-state').hidden=filtered.length>0;document.querySelector('#search-summary').textContent=query?'找到 '+filtered.length+' 位相关桥友':'';document.querySelectorAll('[data-mentor]').forEach(b=>b.onclick=()=>{const m=mentors.find(m=>m.name===b.dataset.mentor);show(`<span class="kicker">MEET YOUR BRIDGE / 示例桥友</span><h2>${m.name} · ${m.role}</h2><p>${m.text}</p><div class="dialog-note">交流前可以准备：<br>① 当前遇到的具体问题<br>② 简历、作品集或相关经历<br>③ 希望这次交流获得的帮助</div><p>这是 Web UX 概念演示，不会发送真实消息或创建预约。</p><a class="dark-btn" href="web.html?view=workspace">查看交流准备工作台 ↗</a>`)})}render();
document.querySelectorAll('[data-domain]').forEach(b=>b.onclick=()=>{domain=b.dataset.domain;document.querySelectorAll('[data-domain]').forEach(t=>{t.classList.toggle('active',t===b);t.setAttribute('aria-pressed',String(t===b))});render()});document.querySelector('#mentor-search').onsubmit=e=>{e.preventDefault();query=document.querySelector('#query').value.trim();domain='all';document.querySelectorAll('[data-domain]').forEach(t=>{t.classList.toggle('active',t.dataset.domain==='all');t.setAttribute('aria-pressed',String(t.dataset.domain==='all'))});render();document.querySelector('#mentors').scrollIntoView()};document.querySelectorAll('[data-query]').forEach(b=>b.onclick=()=>{document.querySelector('#query').value=b.dataset.query;document.querySelector('#mentor-search').requestSubmit()});
const articles=[['作品集的第一句话，应该先说什么？','先说明你要解决的问题，再说明你做了什么。读者需要知道当时的情境、用户遇到的困难，以及你的设计目标。','选择一个关键设计决策，说明你考虑过哪些方案、为什么作出这个选择，以及还有什么没有得到验证。'],['不确定下一步，先把问题拆小。','把职业困惑写成具体的问题：我喜欢做哪些工作？我目前最想补充哪一种能力？我想进一步了解哪一种岗位？','选择一个最小行动，例如整理一个项目、和一位相关领域的桥友交流，或尝试完成一次小任务。'],['一次好的交流，从准备开始。','提前写下自己的背景、目前的问题和期待获得的帮助。比起笼统地询问建议，具体的情境更容易让对方理解你。','结束时，记下一个可以执行的下一步，并确认是否需要后续交流。']];document.querySelectorAll('[data-article]').forEach(b=>b.onclick=()=>{const a=articles[Number(b.dataset.article)];show(`<span class="kicker">COMMUNITY NOTES / 演示内容</span><h2>${a[0]}</h2><p>${a[1]}</p><p>${a[2]}</p>`) });
document.querySelector('#confirm-meeting').onclick=e=>{e.currentTarget.textContent='已确认';e.currentTarget.disabled=true;document.querySelector('#appointments .status').textContent='已确认';document.querySelector('#meeting-feedback').textContent='演示安排已确认。实际预约与通知服务尚未连接。'};document.querySelectorAll('.check-row input').forEach(c=>c.onchange=()=>{const n=document.querySelectorAll('.check-row input:checked').length;document.querySelector('#task-count').textContent=n+' / 3';document.querySelector('.task-progress>div').style.width=n/3*100+'%'});
